pub fn check_all_lowercase(v: &Vec<char>) -> bool {
    // Non-empty, and every character must be between 'a' and 'z'
    if v.is_empty() {
        return false;
    }
    v.iter().all(|&c| c.is_ascii_lowercase())
}

pub fn solve(input: Vec<char>) -> Vec<char> {
    if check_all_lowercase(&input) {
        vec!['a']
    } else {
        vec!['A']
    }
}

