    #[test]
    fn test_all_lowercase() {
        assert_eq!(check_all_lowercase(&vec!['a', 'b', 'z']), true);
        assert_eq!(check_all_lowercase(&vec!['a', 'B', 'c']), false);
        assert_eq!(check_all_lowercase(&vec![]), false);
    }

    #[test]
    fn test_solve() {
        assert_eq!(solve(vec!['h', 'e', 'l', 'l', 'o']), vec!['a']);
        assert_eq!(solve(vec![]), vec!['A']);
        assert_eq!(solve(vec!['H', 'i']), vec!['A']);
        assert_eq!(solve(vec!['a', 'b', 'C']), vec!['A']);
    }
